// Generate the contract types for TS, PHP, Python and Go from packages/core/schema/contract.json.
//   bun tools/gen-types.ts          write
//   bun tools/gen-types.ts --check  fail if a generated file is stale
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const schema = JSON.parse(readFileSync(root + "packages/core/schema/contract.json", "utf8"));
const defs: Record<string, any> = schema.$defs;
const ops: Record<string, { input: string | null; output: string; capability?: string; description?: string }> = schema.operations;
const head = "Code generated by tools/gen-types.ts from packages/core/schema/contract.json. DO NOT EDIT.";
const ref = (p: any) => (p.$ref ? p.$ref.split("/").pop() : null);
const cap = (s: string) => s[0].toUpperCase() + s.slice(1);

function ts(): string {
  let o = `// ${head}\n\nexport const CONTRACT_VERSION = ${JSON.stringify(schema.version)};\n\n`;
  for (const [n, d] of Object.entries(defs)) {
    o += d.description ? `/** ${d.description} */\n` : "";
    o += `export interface ${n} {\n`;
    for (const [k, p] of Object.entries<any>(d.properties)) {
      const t = ref(p) ?? (p.enum ? p.enum.map((e: string) => JSON.stringify(e)).join(" | ") : p.type === "object" ? "Record<string, unknown>" : p.type);
      o += `  ${p.description ? `/** ${p.description} */ ` : ""}${k}${d.required?.includes(k) ? "" : "?"}: ${t};\n`;
    }
    o += "}\n\n";
  }
  o += "/** Every provider adapter implements this interface. */\nexport interface Provider {\n  readonly id: string;\n";
  for (const [n, op] of Object.entries(ops)) o += `  ${op.description ? `/** ${op.description} */ ` : ""}${n}(${op.input ? `input: ${op.input}` : ""}): Promise<${op.output}>;\n`;
  o += "}\n\nexport type Operation = " + Object.keys(ops).map((k) => JSON.stringify(k)).join(" | ") + ";\n";
  o += "/** the capability flag an operation needs (operations without one are always required) */\nexport const OPERATION_CAPABILITY: Partial<Record<Operation, keyof Capabilities>> = " +
    JSON.stringify(Object.fromEntries(Object.entries(ops).filter(([, v]) => v.capability).map(([k, v]) => [k, v.capability]))) + ";\n";
  return o;
}

function go(): string {
  const gt = (p: any) => ref(p) ? (ref(p)) : p.type === "boolean" ? "bool" : p.type === "object" ? "map[string]any" : "string";
  let o = `// ${head}\n\n// Package contract is the Authfly provider contract (v${schema.version}).\npackage contract\n\nimport "context"\n\nconst Version = ${JSON.stringify(schema.version)}\n\n`;
  for (const [n, d] of Object.entries(defs)) {
    o += `type ${n} struct {\n`;
    for (const [k, p] of Object.entries<any>(d.properties)) {
      const opt = d.required?.includes(k) ? "" : ",omitempty";
      o += `\t${cap(k)} ${ref(p) && !d.required?.includes(k) ? "*" : ""}${gt(p)} \`json:"${k}${opt}"\`\n`;
    }
    o += "}\n\n";
  }
  o += "// Provider is implemented by every provider adapter.\ntype Provider interface {\n";
  for (const [n, op] of Object.entries(ops)) o += `\t${cap(n)}(ctx context.Context${op.input ? `, in ${op.input}` : ""}) (${op.output}, error)\n`;
  return o + "}\n";
}

function py(): string {
  const pt = (p: any) => ref(p) ? `"${ref(p)}"` : p.type === "boolean" ? "bool" : p.type === "object" ? "dict" : "str";
  let o = `# ${head}\nfrom __future__ import annotations\nfrom typing import TypedDict, NotRequired, Protocol\n\nCONTRACT_VERSION = ${JSON.stringify(schema.version)}\n\n`;
  for (const [n, d] of Object.entries(defs)) {
    o += `class ${n}(TypedDict):\n`;
    for (const [k, p] of Object.entries<any>(d.properties)) o += `    ${k}: ${d.required?.includes(k) ? pt(p) : `NotRequired[${pt(p)}]`}\n`;
    o += "\n";
  }
  o += "class Provider(Protocol):\n";
  for (const [n, op] of Object.entries(ops)) o += `    def ${n.replace(/[A-Z]/g, (c) => "_" + c.toLowerCase())}(self${op.input ? `, input: ${op.input}` : ""}) -> ${op.output}: ...\n`;
  return o;
}

function php(): string {
  let o = `<?php\n// ${head}\ndeclare(strict_types=1);\n\nnamespace Authfly\\Contract;\n\nconst VERSION = ${JSON.stringify(schema.version)};\n\n`;
  for (const [n, d] of Object.entries(defs)) {
    o += `/**\n * @phpstan-type ${n} array{${Object.entries<any>(d.properties).map(([k, p]) => `${k}${d.required?.includes(k) ? "" : "?"}: ${ref(p) ? "array" : p.type === "boolean" ? "bool" : p.type === "object" ? "array" : "string"}`).join(", ")}}\n */\n`;
  }
  o += "\n/** Every provider adapter implements this interface. Arrays follow the shapes above. */\ninterface Provider\n{\n";
  for (const [n, op] of Object.entries(ops)) o += `    public function ${n}(${op.input ? "array $input" : ""}): array;\n`;
  return o + "}\n";
}

const out: Record<string, string> = {
  "packages/core/src/contract.ts": ts(),
  "sdk/go/contract/contract.go": Bun.spawnSync(["gofmt"], { stdin: new TextEncoder().encode(go()) }).stdout.toString(),
  "sdk/python/authfly_contract.py": py(),
  "sdk/php/src/Contract.php": php(),
};
let stale = 0;
for (const [p, c] of Object.entries(out)) {
  const f = root + p;
  if (process.argv.includes("--check")) {
    if (!existsSync(f) || readFileSync(f, "utf8") !== c) { console.error("stale: " + p); stale++; }
  } else { mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, c); console.log("wrote " + p); }
}
process.exit(stale ? 1 : 0);
